#include <iostream>
#include <string>
using namespace std;

template <typename T>
class Box {
    T value_;

public:
    Box(T value) : value_(value) {}
    T get() const { return value_; }
};

int main() {
    Box<int> a(7);
    Box<string> b("Goa");
    cout << a.get() << " " << b.get() << endl;
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

template <typename T>
class Stack {
    vector<T> items_;

public:
    void push(const T& x) { items_.push_back(x); }
    T pop() {
        T x = items_.back();
        items_.pop_back();
        return x;
    }
    bool empty() const { return items_.empty(); }
};

int main() {
    Stack<int> s;
    s.push(1);
    s.push(2);
    s.push(3);
    while (!s.empty()) {
        cout << s.pop() << " ";
    }
    cout << endl;
    return 0;
}

